@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private Channel? activeChannel;
    private int activeChannelId;

    private bool threadOpen;
    private int? threadRootId;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    private IJSObjectReference? scrollModule;
    private DotNetObjectReference<Chat>? dotNetRef;
    private CancellationTokenSource cts = new();

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            scrollModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-6ca127533e1a4ccaa153d0c87b1d00c2/chat-scroll.js");
            await scrollModule.InvokeVoidAsync("initScrollDetection", ".message-list", dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        await LoadOlderMessages();
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        hasMoreMessages = true;
        threadReplyCounts = [];

        CloseThread();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        hasMoreMessages = loaded.Count == PageSize;

        await BuildThreadReplyCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
        hasMoreMessages = older.Count == PageSize;
        messages.InsertRange(0, older);
        await BuildThreadReplyCounts();

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootId = null;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootId.Value);
        threadReplies.Add(reply);

        // Update reply count
        threadReplyCounts[threadRootId.Value] =
            threadReplyCounts.GetValueOrDefault(threadRootId.Value) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update local state
        UpdateReactionLocally(messages, args.MessageId, args.Emoji);
        if (threadOpen)
        {
            UpdateReactionLocally(threadReplies, args.MessageId, args.Emoji);
            if (threadRootMessage?.Id == args.MessageId)
            {
                UpdateReactionOnMessage(threadRootMessage, args.Emoji);
            }
        }
    }

    private static void UpdateReactionLocally(List<Message> messageList, int messageId, string emoji)
    {
        var idx = messageList.FindIndex(m => m.Id == messageId);
        if (idx >= 0)
        {
            UpdateReactionOnMessage(messageList[idx], emoji);
        }
    }

    private static void UpdateReactionOnMessage(Message message, string emoji)
    {
        var existing = message.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            existing.Users.Add("You");
        }
        else
        {
            message.Reactions.Add(new Reaction(emoji, ["You"]));
        }
    }

    private async Task BuildThreadReplyCounts()
    {
        // Check each message that could be a thread root (has no ReplyToId)
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            if (!threadReplyCounts.ContainsKey(msg.Id))
            {
                var thread = await ChatService.GetThreadAsync(msg.Id);
                if (thread.Count > 0)
                {
                    threadReplyCounts[msg.Id] = thread.Count;
                }
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        await cts.CancelAsync();
        cts.Dispose();
        if (scrollModule is not null)
        {
            await scrollModule.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
