toolArgs.file_text:
/* ── Layout ─────────────────────────────────────────── */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    overflow-y: auto;
    border-right: 1px solid #202225;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #72767d;
    font-size: 1.2rem;
}

/* ── Channel List ──────────────────────────────────── */
::deep .channel-list {
    padding: 12px 0;
}

::deep .channel-list-header {
    padding: 8px 16px;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #8e9297;
    margin: 0;
}

::deep .channel-item {
    display: flex;
    flex-direction: column;
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 8px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #34373c;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-name {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 0.95rem;
    font-weight: 500;
}

::deep .unread-badge {
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

::deep .channel-desc {
    font-size: 0.75rem;
    color: #72767d;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ── Message Area ──────────────────────────────────── */
::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #72767d;
    font-size: 0.85rem;
}

/* ── Message Item ──────────────────────────────────── */
::deep .message-item {
    position: relative;
    padding: 6px 8px;
    border-radius: 4px;
    margin-bottom: 4px;
    transition: background 0.1s;
}

::deep .message-item:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

::deep .timestamp {
    font-size: 0.75rem;
    color: #72767d;
}

::deep .message-content {
    margin: 2px 0 4px;
    font-size: 0.93rem;
    line-height: 1.4;
    word-wrap: break-word;
}

/* Reactions */
::deep .reactions {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-top: 4px;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #393c43;
    border-color: #5865f2;
}

/* Thread link */
::deep .thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* Hover actions */
::deep .hover-actions {
    position: absolute;
    top: -12px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #202225;
    border-radius: 4px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.8rem;
    padding: 4px 8px;
    border-radius: 3px;
    cursor: pointer;
    white-space: nowrap;
}

::deep .action-btn:hover {
    background: #393c43;
    color: #fff;
}

/* Emoji picker */
::deep .emoji-picker {
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #202225;
    border-radius: 6px;
    padding: 6px;
    margin-top: 4px;
    width: fit-content;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

::deep .emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .emoji-btn:hover {
    background: #393c43;
}

/* ── Message Input ─────────────────────────────────── */
::deep .message-input {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #202225;
    flex-shrink: 0;
}

::deep .message-input textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 6px;
    color: #dcddde;
    padding: 10px 14px;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-input textarea::placeholder {
    color: #72767d;
}

::deep .btn-send {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 18px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

::deep .btn-send:hover {
    background: #4752c4;
}

::deep .btn-send:disabled {
    background: #4f545c;
    cursor: not-allowed;
}

/* ── Thread Panel ──────────────────────────────────── */
